"""Build the code-only Quality KPI updater; no saved cockpit data is embedded."""
from pathlib import Path
import zipfile
r=Path(__file__).resolve().parent.parent
patch=(r/'scripts/quality/complaint-rate-patch.js').read_text();assert '</script' not in patch.lower()
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quality KPI updater</title><style>body{font:16px/1.6 system-ui,sans-serif;background:#f3f5f3;color:#17211c;margin:0;padding:24px}main{max-width:740px;margin:auto;background:white;border:1px solid #d8dfd9;border-radius:10px;padding:28px}h1{font-size:25px;margin-top:0}label{font-weight:650;display:block}input{font:inherit;max-width:100%}#status{background:#f3f5f3;padding:14px}a{display:inline-block;background:#17211c;color:white;padding:12px 16px;border-radius:7px;text-decoration:none}a[hidden]{display:none}.note{font-size:14px;color:#55615a}@media(max-width:600px){body{padding:12px}main{padding:18px}}</style></head><body><main><h1>Show both Quality complaint rates</h1><p>Add complaints per million units beside the existing complaints per thousand units.</p><ol><li>Save your current cockpit.</li><li>Select that latest saved HTML file below.</li><li>Download the updated copy and open Quality → Overview.</li></ol><label for="source">Choose your saved cockpit HTML</label><input id="source" type="file" accept=".html,.htm"><p id="status" role="status" aria-live="polite">No file selected.</p><a id="download" hidden>Download updated cockpit</a><p class="note">Both KPIs use the same dates, unit, complaints and production volume. Per million uses the unrounded rate.</p><p class="note">Everything runs on your PC. Nothing is uploaded. Your saved records, previous amendments and original file are retained.</p></main><script>'''+patch+'''
(function(){'use strict';const input=document.getElementById('source'),status=document.getElementById('status'),download=document.getElementById('download');let url,request=0;
input.onchange=async()=>{const current=++request;download.hidden=true;try{const file=input.files[0];if(!file)return;status.textContent='Checking your saved cockpit…';const original=await file.text();if(current!==request)return;
const revised=applyComplaintMillionRate(original);if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([revised],{type:'text/html'}));download.href=url;download.download=file.name.replace(/\\.html?$/i,'')+'_Quality_Both_Rates.html';download.hidden=false;status.textContent='Ready. Download and open the updated cockpit to see both rates in Quality → Overview.';
}catch(error){if(current===request)status.textContent=error.message;}};})();</script></body></html>'''
(r/'Cockpit_Quality_Rates_Updater.html').write_text(html)
with zipfile.ZipFile(r/'Cockpit_Quality_Rates_Updater.zip','w',zipfile.ZIP_DEFLATED) as z:
 for name in ['Cockpit_Quality_Rates_Updater.html','Cockpit_Quality_Rates_Guide.md']:z.write(r/name,name)
print('Built code-only Quality rates updater and ZIP')
